#!/usr/bin/env bash
# Commits and pushes the data files generated by a workflow run.
#
# Usage: bash scripts/commit_data.sh "commit message" [path ...]     (default path: public/data/)
#
# Policy when other workflows pushed to the branch in the meantime:
#   - files this run did NOT change keep whatever the remote has;
#   - files this run DID change are re-applied as whole files on top of the latest remote
#     (last writer wins). Whole files, never hunk-by-hunk, so two runs of a generated JSON
#     are never mixed into an inconsistent hybrid.
#   - if the push is rejected (someone pushed in between), it retries from a fresh fetch.
# Exits non-zero if it cannot push, so a lost data commit is never silent.
set -euo pipefail

MSG="${1:?usage: commit_data.sh \"commit message\" [path ...]}"
shift || true
if [ "$#" -eq 0 ]; then PATHS=("public/data/"); else PATHS=("$@"); fi
BRANCH="${DATA_BRANCH:-main}"
MAX_ATTEMPTS="${MAX_ATTEMPTS:-5}"

git config user.name "github-actions[bot]"
git config user.email "github-actions[bot]@users.noreply.github.com"

git add -A -- "${PATHS[@]}"
if git diff --cached --quiet; then
  echo "No data changes to commit"
  exit 0
fi

# Snapshot of what this run generated (changed/added files and deleted files).
SNAP="$(mktemp -d)"
trap 'rm -rf "$SNAP"' EXIT
mkdir -p "$SNAP/files"
git diff --cached --no-renames --name-only --diff-filter=ACMR -z > "$SNAP/changed.lst"
git diff --cached --no-renames --name-only --diff-filter=D -z > "$SNAP/deleted.lst"
xargs -r -0 -a "$SNAP/changed.lst" -I{} cp -a --parents {} "$SNAP/files/"

for attempt in $(seq 1 "$MAX_ATTEMPTS"); do
  git fetch --quiet origin "$BRANCH"
  git reset --quiet --hard "origin/$BRANCH"     # fresh base: keeps other workflows' commits
  cp -a "$SNAP/files/." .                        # re-apply this run's generated files
  xargs -r -0 -a "$SNAP/deleted.lst" rm -f --
  git add -A -- "${PATHS[@]}"
  if git diff --cached --quiet; then
    echo "The remote already has these data"
    exit 0
  fi
  git commit --quiet -m "$MSG"
  if git push --quiet origin "HEAD:$BRANCH"; then
    echo "Data pushed (attempt $attempt)"
    exit 0
  fi
  echo "Push rejected (attempt $attempt/$MAX_ATTEMPTS); retrying from a fresh fetch..."
  sleep $((attempt * 3))
done

echo "::error::Could not push the data commit after $MAX_ATTEMPTS attempts"
exit 1
